import * as vscode from 'vscode';
import { ApiMessage } from "../Common/Constants";
import ApiExecuteData from "./ApiExecuteData";
import { registerApi } from "./ApiScheduler";


export default class BreakpointApis {

    @registerApi(ApiMessage.getActionMsg("toggle breakpoint"))
    public async toggleBreakpointAtLine(line: number | undefined = undefined): Promise<ApiExecuteData> {
        const apiExecuteData = new ApiExecuteData();
        try {
            const editor = vscode.window.activeTextEditor;
            if (editor && line !== undefined) {
                const position = new vscode.Position(line - 1, 0);
                editor.selection = new vscode.Selection(position, position);
                await vscode.commands.executeCommand('revealLine', { lineNumber: line - 1, at: 'center' });
            }
            await vscode.commands.executeCommand('editor.debug.action.toggleBreakpoint');
            apiExecuteData.executeSuccess("Successfully toggled breakpoint.");
        } catch (e) {
            apiExecuteData.executeFailed(`Failed to toggle breakpoint. ${e}`);
        }
        return apiExecuteData;
    }
}

import { ArgumentMissingError } from "../Error/SmartVscodeError";
import { Chat } from "../ViewProvider";

export default class Api {
    public name: string;
    // "key" or "key=defaultValue"
    public arguments: string[];
    public executer: Function;
    public needConfirm: boolean;
    public toUserMsg: string;


    constructor(name: string, parameters: string[], executer: Function, toUserMsg: string, needConfirm: boolean = false) {
        this.name = name;
        this.arguments = parameters;
        this.executer = executer;
        this.needConfirm = needConfirm;
        this.toUserMsg = toUserMsg;
    }

    public run(args: Object, chat?: Chat) {
        const argValues = this.arguments.map(argument => {
            if (argument === "chat") {
                return chat;
            }
            else if (argument.includes("=")) {
                const key = argument.split("=")[0];
                const defaultValue = argument.split("=")[1];
                const value = key in args ? args[key] : defaultValue;
                return value === "void0" ? undefined : value;
            } else if (args[argument] !== undefined) {
                return args[argument];
            } else {
                throw new ArgumentMissingError(`Argument ${argument} is required for API ${this.name}`);
            }
        });
        return this.executer(...argValues);
    }

}

import * as vscode from 'vscode';
import { ApiMessage } from "../Common/Constants";
import ApiExecuteData from "./ApiExecuteData";
import { registerApi } from "./ApiScheduler";


export default class ConnectApis {
    @registerApi(ApiMessage.getActionMsg("create remote SSH server connect"))
    public async createRemoteSSHServerConnect() {
        const apiExecuteData = new ApiExecuteData();

        if (!this.isRemoteExtensionInstalled()) {
            apiExecuteData.executeFailed("Failed to open remote argument input window, please install ms-vscode-remote.remote-ssh extension first.");
        }
        await vscode.commands.executeCommand('workbench.view.remote');
        await vscode.commands.executeCommand('opensshremotes.addNewSshHost');
        apiExecuteData.executeSuccess("Successfully opened remote argument input window.");
        return apiExecuteData;
    }

    @registerApi(ApiMessage.getActionMsg("open remote config file"))
    public async openRemoteConfigFile() {
        const apiExecuteData = new ApiExecuteData();
        if (!this.isRemoteExtensionInstalled()) {
            apiExecuteData.executeFailed("Failed to open remote argument input window, please install ms-vscode-remote.remote-ssh extension first.");
        }
        await vscode.commands.executeCommand('opensshremotes.openConfigFile');
        apiExecuteData.executeSuccess("Successfully opened remote config file.");
        return apiExecuteData;
    }

    public async isRemoteExtensionInstalled() {
        return vscode.extensions.getExtension('ms-vscode-remote.remote-ssh') !== undefined;
    }
}

export default class ApiExecuteData {
    public success: boolean;

    public toModelMsg: string;

    public toUserMsg: string | undefined;

    public stopTask = false;


    constructor() {
        this.success = false;
        this.toModelMsg = '';
        this.toUserMsg = undefined;
    }

    public executeFailed(toModelMsg?: string, toUserMsg?: string) {
        this.success = false;
        this.toModelMsg = toModelMsg || this.toModelMsg;
        this.toUserMsg = toUserMsg || this.toUserMsg;
    }

    public executeSuccess(toModelMsg?: string, toUserMsg?: string) {
        this.success = true;
        this.toModelMsg = toModelMsg || this.toModelMsg;
        this.toUserMsg = toUserMsg || this.toUserMsg;
    }
}

